import{_ as t,o as r,c as s,ah as a}from"./chunks/framework.CRsDMGp2.js";const m=JSON.parse('{"title":"Guide — Administrateur","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/administrateur.md","filePath":"src/guide/administrateur.md"}'),o={name:"guide/administrateur.md"};function i(n,e,u,l,d,c){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="guide-—-administrateur" tabindex="-1">Guide — Administrateur <a class="header-anchor" href="#guide-—-administrateur" aria-label="Permalink to &quot;Guide — Administrateur&quot;">​</a></h1><p>Administrer comptes, facturation et sécurité.</p><p>En tant qu&#39;Administrateur, vous disposez d&#39;un accès complet à la plateforme.</p><h2 id="gestion-des-comptes-et-des-acces" tabindex="-1">Gestion des comptes et des accès <a class="header-anchor" href="#gestion-des-comptes-et-des-acces" aria-label="Permalink to &quot;Gestion des comptes et des accès&quot;">​</a></h2><ul><li>Créez et gérez les comptes utilisateurs (internes, clients, partenaires, apporteurs d&#39;affaires) depuis <strong>Utilisateurs</strong>, et attribuez-leur un rôle.</li><li>Créez aussi depuis <strong>Utilisateurs</strong> les comptes des <strong>contributeurs externes</strong> des pôles Commercial, Support, RH et Facturation, en choisissant le rôle du pôle concerné. Vous seul créez et révoquez ces comptes ; pour révoquer un accès, suspendez le compte. Un collaborateur ou un expert externe que le pôle RH doit pouvoir affecter à un projet a d&#39;abord besoin de son propre compte.</li><li>Gérez les organisations (clients, partenaires) depuis <strong>Organisations</strong>.</li><li>Paramétrez les <strong>types de projet</strong> depuis <strong>Types de projet</strong> : phases, jalons et pourcentages de facturation par défaut de chaque type — ce sont ces modèles qui pré-remplissent automatiquement un nouveau projet à sa création par un chef de projet.</li></ul><h2 id="facturation" tabindex="-1">Facturation <a class="header-anchor" href="#facturation" aria-label="Permalink to &quot;Facturation&quot;">​</a></h2><ul><li>Générez et envoyez la facture correspondante (acompte, intermédiaire, solde ou équipement) lorsqu&#39;un jalon facturable est validé par le chef de projet.</li><li>Générez le <strong>bon de livraison</strong> et l&#39;<strong>attestation de bonne fin d&#39;exécution</strong>, puis envoyez-les en signature électronique au client.</li><li>Créez librement des devis et des factures pro forma, y compris avant la création d&#39;un projet, depuis <strong>Devis</strong> et <strong>Factures pro forma</strong>.</li><li>Configurez et supervisez les moyens de paiement en ligne (Mobile Money, carte bancaire) et suivez les paiements reçus depuis la fiche de facturation de chaque projet.</li></ul><h2 id="ecosysteme-externe" tabindex="-1">Écosystème externe <a class="header-anchor" href="#ecosysteme-externe" aria-label="Permalink to &quot;Écosystème externe&quot;">​</a></h2><ul><li>Paramétrez le taux de commission de chaque apporteur d&#39;affaires depuis sa fiche utilisateur (couramment entre 5 et 15 %, ajustable au cas par cas) et suivez le cumul de ses commissions dues et versées.</li><li>Validez les factures déposées par les partenaires sur l&#39;onglet <strong>Paiements partenaires</strong> de chaque projet, et enregistrez leur règlement une fois celui-ci effectué.</li><li>Générez le document d&#39;avenant sur demande du chef de projet et suivez sa signature par le client.</li><li>Depuis la fiche d&#39;un partenaire ou d&#39;un apporteur d&#39;affaires, téléchargez les gabarits de contrat vierges (contrat-cadre, fiche de mission, convention de confidentialité, contrat de mandat) à leur transmettre — cette action est également disponible au chef de projet depuis l&#39;équipe d&#39;un projet.</li></ul><h2 id="soumissions-des-poles" tabindex="-1">Soumissions des pôles <a class="header-anchor" href="#soumissions-des-poles" aria-label="Permalink to &quot;Soumissions des pôles&quot;">​</a></h2><p>La page <strong>Soumissions des pôles</strong> rassemble ce que les contributeurs externes envoient et qui attend votre intervention :</p><ul><li><strong>Demandes de projet</strong> (pôle Commercial) : choisissez le client — le client existant correspondant, ou sa création s&#39;il est nouveau —, désignez le chef de projet, ajustez le nom si besoin, puis cliquez sur <strong>Créer le projet</strong>. Le projet est créé avec sa référence (<code>NAIA-0142</code>) et le chef de projet est notifié.</li><li><strong>Besoins de développement à trier</strong> (pôles Support et Commercial) : un besoin envoyé sans projet connu attend ici que vous choisissiez le projet concerné. <strong>Créer la tâche</strong> l&#39;ajoute au projet, avec un badge indiquant son origine.</li><li><strong>Écarter</strong> retire une soumission invalide ; elle disparaît de la liste de son auteur, et le journal d&#39;audit en garde la trace.</li></ul><p>Vous êtes notifié, dans l&#39;application et par e-mail, à chaque nouvelle soumission.</p><h2 id="blocage-pour-impaye-et-securite" tabindex="-1">Blocage pour impayé et sécurité <a class="header-anchor" href="#blocage-pour-impaye-et-securite" aria-label="Permalink to &quot;Blocage pour impayé et sécurité&quot;">​</a></h2><ul><li>Quand le pôle Facturation signale un paiement <strong>en retard</strong>, vous êtes alerté, comme la Direction. Depuis la fiche du projet, décidez de <strong>Bloquer le projet</strong> ou de <strong>Ne pas bloquer</strong>. Quand le paiement est revenu à jour, <strong>débloquez le projet</strong>.</li><li>Le blocage est un verrou « doux » : les tâches déjà démarrées se terminent, mais personne — chef de projet compris — ne peut démarrer une nouvelle tâche ni valider un jalon. Tout le reste reste possible, y compris payer. Seul le projet concerné est bloqué, jamais les autres projets du client.</li><li>Consultez le <strong>journal d&#39;audit</strong> pour retracer les actions effectuées sur la plateforme.</li><li>Gérez les aspects de sécurité de votre propre compte (mot de passe, authentification à deux facteurs) depuis <strong>Paramètres &gt; Sécurité</strong> — activer la 2FA vous est proposé automatiquement à la connexion.</li></ul><h2 id="support-de-premier-niveau" tabindex="-1">Support de premier niveau <a class="header-anchor" href="#support-de-premier-niveau" aria-label="Permalink to &quot;Support de premier niveau&quot;">​</a></h2><p>Vous assurez le support de premier niveau aux utilisateurs de la plateforme.</p><p><strong>Canaux :</strong> la messagerie intégrée à un projet est le canal prioritaire (conserve l&#39;historique dans son contexte) ; un e-mail de support dédié couvre les demandes hors contexte d&#39;un projet précis (ex. problème de connexion).</p><p><strong>Catégorisation des demandes :</strong></p><table tabindex="0"><thead><tr><th>Catégorie</th><th>Exemples</th><th>Délai de première réponse indicatif</th></tr></thead><tbody><tr><td>Accès / connexion</td><td>Mot de passe oublié, compte suspendu à tort, 2FA bloquante</td><td>4 heures ouvrées</td></tr><tr><td>Facturation / paiement</td><td>Facture non reçue, paiement en ligne échoué, désaccord sur un montant</td><td>1 jour ouvré</td></tr><tr><td>Fonctionnel</td><td>Question d&#39;utilisation, comportement inattendu d&#39;une fonctionnalité</td><td>1 jour ouvré</td></tr><tr><td>Anomalie technique</td><td>Erreur bloquante, page inaccessible</td><td>4 heures ouvrées, escalade immédiate si bloquant</td></tr></tbody></table><p><strong>Traitement :</strong> accusez réception → qualifiez la catégorie et vérifiez que la personne a légitimement accès à la ressource concernée → traitez directement si la résolution relève de vous (réinitialisation d&#39;accès, correction de facture, déblocage d&#39;un projet) → sinon, escaladez vers l&#39;équipe de développement pour toute anomalie technique → confirmez la résolution auprès du demandeur.</p>',21)])])}const g=t(o,[["render",i]]);export{m as __pageData,g as default};
